<script setup lang="ts">
import {ref, computed, onMounted, onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAccount} from './store'
import {api} from './api'
const isDemo=import.meta.env.MODE==='demo'
const account=useAccount(), route=useRoute(), router=useRouter()
const phone=ref(''),code=ref(''),error=ref(''),busy=ref(false),accountOpen=ref(false),mobileOpen=ref(false),prefs=ref<any>({}),consent=ref(false)
const nav=[['/chat','智能助手','◌'],['/shops','发现店铺','⌕'],['/community','探店社区','▤'],['/orders','我的订单','▥'],['/coupons','我的券包','▱']]
const title=computed(()=>nav.find(n=>route.path.startsWith(n[0]))?.[1]||'CityLens')
function expired(){account.clear();accountOpen.value=false}
onMounted(()=>{account.boot();window.addEventListener('auth-expired',expired)})
onUnmounted(()=>window.removeEventListener('auth-expired',expired))
async function run(fn:()=>Promise<unknown>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function settings(){accountOpen.value=true;await run(async()=>{prefs.value=(await api('/api/memory')).preferences||{}})}
async function deleteSession(id:string){if(!confirm('删除此会话？'))return;await run(async()=>{await api(`/api/sessions/${id}`,'DELETE');await account.refreshSessions();if(route.params.id===id)await router.push('/chat')})}
async function newChat(){mobileOpen.value=false;await router.push('/chat');window.dispatchEvent(new Event('new-chat'))}
function go(path:string){mobileOpen.value=false;router.push(path)}
</script>
<template>
<div class="shell"><aside :class="['sidebar',{open:mobileOpen}]"><div class="brand">CityLens<small>你的城市生活助手</small></div><button class="primary new-chat" :disabled="!account.user" @click="newChat">＋ 开启新对话</button><nav><button v-for="item in nav" :key="item[0]" :class="{active:route.path.startsWith(item[0])}" @click="go(item[0])"><span>{{item[2]}}</span>{{item[1]}}</button></nav><div class="history"><div class="eyebrow">最近会话</div><div v-for="s in account.sessions" :key="s.session_id" :class="['history-item',{selected:route.params.id===s.session_id}]"><button @click="go('/chat/'+s.session_id)">{{s.title}}</button><button class="delete" aria-label="删除会话" @click="deleteSession(s.session_id)">×</button></div><p v-if="!account.sessions.length" class="muted small">登录后，对话会保存在这里。</p></div><button class="account" @click="account.user&&!isDemo?settings():null"><span class="avatar">{{account.user?.nickName?.slice(0,1)||'你'}}</span><span><b>{{account.user?.nickName||'请先登录'}}</b><small>{{isDemo?'无需登录 · 刷新重置':'账号与长期偏好'}}</small></span><span class="dots">···</span></button></aside><main class="workspace"><header><button class="mobile-menu" @click="mobileOpen=!mobileOpen" aria-label="导航">☰</button><div><h1>{{title}}</h1><small class="muted">一起安排城市生活</small></div><div class="header-right"><span class="badge">点评 × Agent</span><a v-if="!isDemo" href="/legacy" class="small muted">旧版入口</a><a v-else href="https://github.com/jamezhuang/citylens-agent" target="_blank" rel="noopener noreferrer" class="small muted">GitHub ↗</a></div></header><div v-if="isDemo" class="demo-banner"><b>公开演示版</b><span>固定案例回放 · 合成商户 · 浏览器模拟订单</span><a href="https://github.com/jamezhuang/citylens-agent/blob/main/docs/DEMO.md" target="_blank" rel="noopener noreferrer">查看项目说明 ↗</a></div><div class="global-error" v-if="error" role="alert">{{error}}</div><RouterView v-if="account.user" :key="account.generation"/><div v-else class="login-page"><div class="login-card"><div class="eyebrow">WELCOME TO CITYLENS</div><h2>先登录，再一起探索城市</h2><p class="muted">聊天、探店社区、订单和券包使用同一个点评账号。</p><form @submit.prevent="run(()=>account.login(phone,code))"><label>手机号<input v-model="phone" required pattern="1[3-9][0-9]{9}" maxlength="11" inputmode="tel" autocomplete="tel" placeholder="请输入手机号"></label><label>验证码<div class="inline"><input v-model="code" required pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" placeholder="6 位验证码"><button type="button" class="outline" :disabled="busy||!/^1[3-9]\d{9}$/.test(phone)" @click="run(async()=>{await api('/api/auth/code','POST',{phone});error='验证码已生成，本地演示环境请查看 Java 日志。'})">获取验证码</button></div></label><button class="primary" :disabled="busy||!account.ready">{{busy?'正在处理…':'登录 CityLens'}}</button></form><p class="small muted">本地演示库不发送真实短信；支付仅为本地模拟。</p></div></div></main></div>
<div class="overlay" v-if="accountOpen" @click.self="accountOpen=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="account-title"><button class="close" aria-label="关闭" @click="accountOpen=false">×</button><h2 id="account-title">账号与长期偏好</h2><p>{{account.user?.nickName}}</p><label>常选类别<input v-model="prefs.category" maxlength="30" placeholder="例如：美食、KTV"></label><label>常用商圈<input v-model="prefs.area" maxlength="30" placeholder="例如：运河上街"></label><div class="inline"><label>人均预算上限<input type="number" v-model.number="prefs.max_price" min="1" max="100000" placeholder="元"></label><label>最低评分<input type="number" v-model.number="prefs.min_score" min="0" max="5" step="0.1"></label></div><label class="check"><input type="checkbox" v-model="prefs.wants_coupon">优先查看优惠券</label><label class="check"><input type="checkbox" v-model="prefs.wants_notes">推荐时查看探店笔记</label><label class="check"><input type="checkbox" v-model="consent">我同意保存这些偏好，用于跨会话推荐</label><div class="actions"><button class="outline" :disabled="busy" @click="run(()=>account.logout());accountOpen=false">退出登录</button><button class="outline" :disabled="busy" @click="run(async()=>{await api('/api/memory','DELETE');prefs={}})">清除记忆</button><button class="primary" :disabled="busy||!consent" @click="run(()=>api('/api/memory','PUT',{consent:true,preferences:{...prefs,category:prefs.category||null,area:prefs.area||null,max_price:prefs.max_price||null,min_score:prefs.min_score===''?null:prefs.min_score}}))">保存偏好</button></div></section></div>
</template>
